1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Counts the members of an owner's household: the owners sharing this owner's last name and address,
10	 * compared case-insensitively with collapsed whitespace (the same grouping
11	 * {@link RejectDuplicateOwnerHousehold} uses). The owner itself is included, so a freshly created
12	 * owner counts towards its own household total.
13	 */
14	public final class HouseholdSize {
15	
16	    private HouseholdSize() {
17	    }
18	
19	    public static int of(Owner owner, OwnerRepository repository) {
20	        String lastName = normalize(owner.getLastName());
21	        String address = normalize(owner.getAddress());
22	        int count = 0;
23	        for (Owner other : repository.findAll()) {
24	            if (lastName.equals(normalize(other.getLastName()))
25	                    && address.equals(normalize(other.getAddress()))) {
26	                count++;
27	            }
28	        }
29	        return count;
30	    }
31	
32	    private static String normalize(String value) {
33	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
34	    }
35	}
